svg.script:
(function () {
  var dark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;

  var colors = dark ? {
    neutral:  { fill: '#2a2a28', stroke: '#c3c2b7', width: 1.5 },
    active:   { fill: '#3a2317', stroke: '#ef7a63', width: 2.5 },
    restart:  { fill: '#3a2317', stroke: '#d95926', width: 3 },
    sent:     { fill: '#4a3f17', stroke: '#d9ad2f', width: 2 },
    queued:   { fill: '#333331', stroke: '#6b6a63', width: 2 },
    deliveredA: { fill: '#3a2317', stroke: '#d95926', width: 2 },
    deliveredB: { fill: '#142a42', stroke: '#3987e5', width: 2 }
  } : {
    neutral:  { fill: '#f2f1ee', stroke: '#52514e', width: 1.5 },
    active:   { fill: '#fdece3', stroke: '#d6563f', width: 2.5 },
    restart:  { fill: '#fdece3', stroke: '#eb6834', width: 3 },
    sent:     { fill: '#fdf3d6', stroke: '#c99a1f', width: 2 },
    queued:   { fill: '#ececea', stroke: '#898781', width: 2 },
    deliveredA: { fill: '#fdece3', stroke: '#eb6834', width: 2 },
    deliveredB: { fill: '#e7f0fb', stroke: '#2a78d6', width: 2 }
  };

  function paint(el, c) {
    el.style.fill = c.fill;
    el.style.stroke = c.stroke;
    el.style.strokeWidth = c.width;
  }

  var steps = [
    { main: 'box1', cap1: 'Szenario A -- Start', cap2: 'Normaler Ablauf beginnt',
      msgA: 'hidden', msgB: 'hidden', restart: false, connA: false, connB: false },
    { main: 'box2', cap1: 'Senden', cap2: 'Enter übermittelt den Entwurf',
      msgA: 'hidden', msgB: 'hidden', restart: false, connA: false, connB: false },
    { main: 'box3', box3: 'active', cap1: 'Verarbeitung beginnt', cap2: 'Tool-Nutzung / Denken läuft',
      msgA: 'hidden', msgB: 'hidden', restart: false, connA: false, connB: false },
    { main: 'box3', box3: 'active', cap1: 'Nutzer schickt nach', cap2: 'Enter gedrückt, während Tools laufen',
      msgA: 'sent', msgB: 'hidden', restart: false, connA: false, connB: false },
    { main: 'box3', box3: 'neutral', cap1: 'Wartet in der Warteschlange', cap2: 'noch nicht zugestellt',
      msgA: 'queued', msgB: 'hidden', restart: false, connA: false, connB: false },
    { main: 'box3', box3: 'restart', cap1: 'Zugestellt -- Verarbeitung läuft erneut an', cap2: 'kommt noch in diesem Turn an',
      msgA: 'delivered', msgB: 'hidden', restart: true, connA: true, connB: false },
    { main: 'box4', cap1: 'Antwort', cap2: 'streamt live',
      msgA: 'hidden', msgB: 'hidden', restart: false, connA: false, connB: false },
    { main: 'box5', cap1: 'Anzeige abgeschlossen', cap2: 'nächster Zyklus beginnt',
      msgA: 'hidden', msgB: 'hidden', restart: false, connA: false, connB: false },
    { main: 'box1', cap1: 'Szenario B -- Start', cap2: 'Normaler Ablauf beginnt erneut',
      msgA: 'hidden', msgB: 'hidden', restart: false, connA: false, connB: false },
    { main: 'box2', cap1: 'Senden', cap2: 'Enter übermittelt den Entwurf',
      msgA: 'hidden', msgB: 'hidden', restart: false, connA: false, connB: false },
    { main: 'box3', box3: 'active', cap1: 'Verarbeitung', cap2: 'läuft normal durch, keine Unterbrechung',
      msgA: 'hidden', msgB: 'hidden', restart: false, connA: false, connB: false },
    { main: 'box4', cap1: 'Antwort beginnt', cap2: 'streamt live',
      msgA: 'hidden', msgB: 'hidden', restart: false, connA: false, connB: false },
    { main: 'box4', cap1: 'Nutzer schickt nach', cap2: 'Enter gedrückt, während Antwort streamt',
      msgA: 'hidden', msgB: 'sent', restart: false, connA: false, connB: false },
    { main: 'box4', cap1: 'Wartet in der Warteschlange', cap2: 'noch nicht zugestellt',
      msgA: 'hidden', msgB: 'queued', restart: false, connA: false, connB: false },
    { main: 'box5', cap1: 'Zugestellt -- startet automatisch als neuer Turn', cap2: 'kein erneutes Enter nötig',
      msgA: 'hidden', msgB: 'delivered', restart: false, connA: false, connB: true }
  ];

  var boxes = { box1: document.getElementById('box1'), box2: document.getElementById('box2'),
    box3: document.getElementById('box3'), box4: document.getElementById('box4'), box5: document.getElementById('box5') };
  var msgAGroup = document.getElementById('msgAGroup');
  var msgBGroup = document.getElementById('msgBGroup');
  var msgABox = document.getElementById('msgABox');
  var msgBBox = document.getElementById('msgBBox');
  var flashA = document.getElementById('flashA');
  var flashB = document.getElementById('flashB');
  var restartCue = document.getElementById('restartCue');
  var capLine1 = document.getElementById('capLine1');
  var capLine2 = document.getElementById('capLine2');
  var stepIndicator = document.getElementById('stepIndicator');
  var step = 1;

  function paintMsg(group, box, flash, state, deliveredKey) {
    if (state === 'hidden') {
      group.style.opacity = '0';
      flash.style.opacity = '0';
      return;
    }
    group.style.opacity = '1';
    if (state === 'sent') { paint(box, colors.sent); flash.style.opacity = '0'; }
    else if (state === 'queued') { paint(box, colors.queued); flash.style.opacity = '0'; }
    else if (state === 'delivered') { paint(box, colors[deliveredKey]); flash.style.opacity = '1'; }
  }

  function render() {
    var s = steps[step - 1];
    Object.keys(boxes).forEach(function (key) {
      if (key === s.main) {
        paint(boxes[key], key === 'box3' && s.box3 ? colors[s.box3] : colors.active);
      } else {
        paint(boxes[key], colors.neutral);
      }
    });
    paintMsg(msgAGroup, msgABox, flashA, s.msgA, 'deliveredA');
    paintMsg(msgBGroup, msgBBox, flashB, s.msgB, 'deliveredB');
    restartCue.style.opacity = s.restart ? '1' : '0';
    document.querySelector('[marker-end="url(#arrow-a)"]').style.opacity = s.connA ? '1' : '0';
    document.querySelector('[marker-end="url(#arrow-b)"]').style.opacity = s.connB ? '1' : '0';
    capLine1.textContent = s.cap1;
    capLine2.textContent = s.cap2;
    stepIndicator.textContent = step + ' / ' + steps.length;
  }

  function next() { step = (step >= steps.length) ? 1 : step + 1; render(); }
  function prev() { step = (step <= 1) ? steps.length : step - 1; render(); }

  document.getElementById('nextBtn').addEventListener('click', next);
  document.getElementById('prevBtn').addEventListener('click', prev);
  document.getElementById('bgClick').addEventListener('click', next);
  document.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowRight' || e.key === ' ') { next(); e.preventDefault(); }
    if (e.key === 'ArrowLeft') { prev(); e.preventDefault(); }
  });

  render();
})();
